def seed_costeo(apps, schema_editor):
    ProductoCosteo = apps.get_model('gestion_gerencial', 'ProductoCosteo')
    InsumoCosteo = apps.get_model('gestion_gerencial', 'InsumoCosteo')
    RecetaLineaCosteo = apps.get_model('gestion_gerencial', 'RecetaLineaCosteo')
    ManoObraCosteo = apps.get_model('gestion_gerencial', 'ManoObraCosteo')
    EquipoCosteo = apps.get_model('gestion_gerencial', 'EquipoCosteo')
    ConfiguracionCosteo = apps.get_model('gestion_gerencial', 'ConfiguracionCosteo')

    insumos_por_nombre = {}
    for ins in INSUMOS:
        obj, _ = InsumoCosteo.objects.get_or_create(
            nombre=ins['nombre'],
            defaults={
                'unidad': ins['unidad'],
                'precio': ins['precio'],
                'comentario': ins['comentario'],
            },
        )
        insumos_por_nombre[ins['nombre']] = obj

    productos_por_codigo = {}
    for prod in PRODUCTOS:
        margen = MARGEN_OBJETIVO.get(prod['codigo'])
        descuento = DESCUENTO_OBJETIVO.get(prod['codigo'])
        obj, _ = ProductoCosteo.objects.get_or_create(
            codigo=prod['codigo'],
            defaults={
                'nombre': prod['nombre'],
                'familia': prod['familia'],
                'peso': prod['peso'],
                'precio_actual': prod['precio_actual'],
                'precio_con_iva': prod['precio_con_iva'],
                'precio_distribuidor': prod['precio_distribuidor'],
                'unidades_mes': prod['unidades_mes'],
                'unidades_lote': prod['unidades_lote'],
                'margen_objetivo': margen,
                'descuento_objetivo': descuento,
            },
        )
        productos_por_codigo[prod['codigo']] = obj

    for codigo, lineas in RECETAS.items():
        prod = productos_por_codigo.get(codigo)
        if not prod:
            continue
        for linea in lineas:
            insumo = insumos_por_nombre.get(linea['insumo'])
